#include <bits/stdc++.h>
using namespace std;

const int MAX_T = 1e5;
const int MAX_N = 1e3;
const int MAX_M = 1e3;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int t;
    cin >> t;
    while (t--) {
        int n, m;
        cin >> n >> m;
        string s[n];
        for (int i = 0; i < n; ++i) {
            cin >> s[i];
        }

        // Precompute for each string, the count of each of the 5 letters
        // and the total count of the 5 letters
        int total_5_letters = 0;
        int max_used = 0;
        for (int i = 0; i < n; ++i) {
            int count_n = 0, count_a = 0, count_r = 0, count_e = 0, count_k = 0;
            for (char c : s[i]) {
                if (c == 'n') count_n++;
                else if (c == 'a') count_a++;
                else if (c == 'r') count_r++;
                else if (c == 'e') count_e++;
                else if (c == 'k') count_k++;
            }
            total_5_letters += count_n + count_a + count_r + count_e + count_k;
            int used = 0;
            // Narek's process: find the letters in order, using the first occurrence
            // So, we need to count how many of the 5 letters are used in the string
            // in the order n, a, r, e, k
            int pos_n = 0, pos_a = 0, pos_r = 0, pos_e = 0, pos_k = 0;
            for (char c : s[i]) {
                if (c == 'n' && pos_n == 0) {
                    pos_n = 1;
                    used++;
                } else if (c == 'a' && pos_a == 0) {
                    pos_a = 1;
                    used++;
                } else if (c == 'r' && pos_r == 0) {
                    pos_r = 1;
                    used++;
                } else if (c == 'e' && pos_e == 0) {
                    pos_e = 1;
                    used++;
                } else if (c == 'k' && pos_k == 0) {
                    pos_k = 1;
                    used++;
                }
            }
            max_used = max(max_used, used);
        }

        // If all 5 letters are used in some string, then the maximum value is 10 - total_5_letters
        // else, it's 0
        int max_score = 0;
        if (max_used == 5) {
            max_score = 10 - total_5_letters;
        }

        cout << max_score << "\n";
    }

    return 0;
}
